import React, { useEffect, useMemo, useRef, useState } from "react";
import { transitionMs } from "./timing";
import {
  AccessibilityInfo,
  PanResponder,
  StyleSheet,
  View,
  type ViewStyle,
} from "react-native";
import {
  Canvas,
  Picture,
  Skia,
  createPicture,
} from "@shopify/react-native-skia";
import {
  Easing,
  useDerivedValue,
  useFrameCallback,
  useSharedValue,
  withTiming,
} from "react-native-reanimated";
import {
  buildData,
  layoutTiles,
  makeConfig,
  paperAlpha,
  tileColor,
  type Modules,
} from "./orbitMath";

export type OrbitQRProps = {
  /** QR matrix, true for a dark module. Create it with any QR encoder. */
  modules: Modules;
  /** Edge length in points. The code keeps a 4 module quiet zone inside it. */
  size: number;
  /** false shows the rotating sphere, true shows the scannable code. */
  showCode: boolean;
  /** Called when a morph reaches its end state. */
  onSettled?: (showCode: boolean) => void;
  reducedMotion?: boolean;
  /** Stretch the transition 4x so it is easy to watch. Optional demo aid. */
  slowMotion?: boolean;
  /** Read by screen readers, for example the URL the code opens. */
  label?: string;
  style?: ViewStyle;
};

const SPIN = 0.00042;

export function OrbitQR({
  modules,
  size,
  showCode,
  onSettled,
  reducedMotion,
  slowMotion,
  label = "QR code",
  style,
}: OrbitQRProps) {
  const [systemReduced, setSystemReduced] = useState(false);
  useEffect(() => {
    let alive = true;
    AccessibilityInfo.isReduceMotionEnabled()
      .then((v) => alive && setSystemReduced(v))
      .catch(() => {});
    const sub = AccessibilityInfo.addEventListener(
      "reduceMotionChanged",
      setSystemReduced,
    );
    return () => {
      alive = false;
      sub.remove();
    };
  }, []);
  const reduced = reducedMotion ?? systemReduced;
  const data = useMemo(() => buildData(modules), [modules]);
  const cfg = useMemo(
    () => makeConfig(size, modules.length, data.count, reduced),
    [size, modules.length, data.count, reduced],
  );

  const progress = useSharedValue(showCode ? 1 : 0);
  const yaw = useSharedValue(0.6);
  const pitch = useSharedValue(-0.28);
  const spin = useSharedValue(SPIN);
  const dragging = useSharedValue(false);
  const settled = useRef(onSettled);
  settled.current = onSettled;

  useEffect(() => {
    progress.value = withTiming(
      showCode ? 1 : 0,
      { duration: transitionMs(reduced, slowMotion), easing: Easing.inOut(Easing.cubic) },
      (finished) => {
        if (finished && settled.current)
          globalThis.requestAnimationFrame?.(() => settled.current?.(showCode));
      },
    );
  }, [showCode, reduced, slowMotion, progress]);

  useFrameCallback((frame) => {
    if (dragging.value || reduced) return;
    const dt = Math.min(frame.timeSincePreviousFrame ?? 16, 48);
    const base = SPIN * (1 - progress.value);
    yaw.value += spin.value * dt;
    spin.value += (base - spin.value) * (1 - Math.exp(-dt / 420));
  });

  const picture = useDerivedValue(() => {
    const p = progress.value;
    const out: number[] = new Array(data.count * 5);
    const order: number[] = [];
    layoutTiles(p, yaw.value, pitch.value, data, cfg, out, order);
    const rgb = [0, 0, 0];
    return createPicture(
      (canvas) => {
        const paint = Skia.Paint();
        paint.setAntiAlias(true);
        const paper = paperAlpha(p);
        if (paper > 0) {
          paint.setColor(Float32Array.of(0.965, 0.973, 0.945, paper));
          canvas.drawRect(Skia.XYWHRect(0, 0, cfg.canvas, cfg.canvas), paint);
        }
        for (let k = 0; k < order.length; k += 1) {
          const i = order[k];
          const x = out[i * 5];
          const y = out[i * 5 + 1];
          const side = out[i * 5 + 2];
          tileColor(out[i * 5 + 3], out[i * 5 + 4], rgb);
          paint.setColor(Float32Array.of(rgb[0], rgb[1], rgb[2], 1));
          canvas.drawRect(
            Skia.XYWHRect(x - side / 2, y - side / 2, side, side),
            paint,
          );
        }
      },
      Skia.XYWHRect(0, 0, cfg.canvas, cfg.canvas),
    );
  });

  const start = useRef({ yaw: 0, pitch: 0 });
  const responder = useMemo(
    () =>
      PanResponder.create({
        onStartShouldSetPanResponder: () => progress.value < 0.2,
        onMoveShouldSetPanResponder: () => progress.value < 0.2,
        onPanResponderGrant: () => {
          dragging.value = true;
          spin.value = 0;
          start.current = { yaw: yaw.value, pitch: pitch.value };
        },
        onPanResponderMove: (_, g) => {
          yaw.value = start.current.yaw + g.dx * 0.011;
          pitch.value = Math.max(
            -1.1,
            Math.min(1.1, start.current.pitch + g.dy * 0.011),
          );
        },
        onPanResponderRelease: (_, g) => {
          spin.value = g.vx * 0.011;
          dragging.value = false;
        },
        onPanResponderTerminate: () => {
          dragging.value = false;
        },
      }),
    [dragging, pitch, progress, spin, yaw],
  );

  return (
    <View
      accessible
      accessibilityRole="image"
      accessibilityLabel={
        showCode ? label : "Rotating sphere of tiles that becomes a QR code"
      }
      style={[{ width: size, height: size }, style]}
      {...responder.panHandlers}
    >
      <Canvas style={StyleSheet.absoluteFill}>
        <Picture picture={picture} />
      </Canvas>
    </View>
  );
}

// Pure maths for Orbit QR. No React Native imports, so it runs on the UI thread,
// on the site and in Node tests. Every function that runs per frame is a worklet.

export type Modules = ReadonlyArray<ReadonlyArray<boolean>>;
export const QUIET_ZONE = 4;
export const WAVE_SPREAD = 0.42;
export const SEAM = 0.8;

export type OrbitData = {
  count: number;
  /** Sphere unit vector for each tile: x, y (down is positive), z (toward viewer). */
  sphere: number[];
  /** Module column and row of each tile. */
  cols: number[];
  rows: number[];
  size: number;
};

export type OrbitConfig = {
  canvas: number;
  radius: number;
  cell: number;
  origin: number;
  focal: number;
  tile: number;
  spread: number;
};

export function darkCells(modules: Modules) {
  const cols: number[] = [];
  const rows: number[] = [];
  modules.forEach((line, r) =>
    line.forEach((on, c) => {
      if (on) {
        cols.push(c);
        rows.push(r);
      }
    }),
  );
  return { cols, rows };
}

export function fibonacciSphere(n: number) {
  const out: number[] = [];
  const golden = Math.PI * (3 - Math.sqrt(5));
  for (let i = 0; i < n; i += 1) {
    const y = n === 1 ? 0 : -1 + (2 * i) / (n - 1);
    const ring = Math.sqrt(Math.max(0, 1 - y * y));
    const a = i * golden;
    out.push(Math.sin(a) * ring, y, Math.cos(a) * ring);
  }
  return out;
}

/**
 * Pair every dark module with a sphere point. Rows of the code become latitude
 * bands of the sphere, and columns follow longitude, so the picture stays
 * coherent while it unfolds. Returns sphere vectors ordered by module.
 */
export function matchSphere(cols: number[], rows: number[]) {
  const n = cols.length;
  const sphere = fibonacciSphere(n);
  const order = Array.from({ length: n }, (_, i) => i).sort(
    (a, b) => sphere[a * 3 + 1] - sphere[b * 3 + 1],
  );
  const modules = Array.from({ length: n }, (_, i) => i).sort(
    (a, b) => rows[a] - rows[b] || cols[a] - cols[b],
  );
  const matched = new Array<number>(n * 3);
  let at = 0;
  while (at < n) {
    let end = at;
    while (end < n && rows[modules[end]] === rows[modules[at]]) end += 1;
    const band = order
      .slice(at, end)
      .sort(
        (a, b) =>
          Math.atan2(sphere[a * 3], sphere[a * 3 + 2]) -
          Math.atan2(sphere[b * 3], sphere[b * 3 + 2]),
      );
    const line = modules.slice(at, end);
    for (let k = 0; k < line.length; k += 1) {
      const m = line[k];
      const s = band[k];
      matched[m * 3] = sphere[s * 3];
      matched[m * 3 + 1] = sphere[s * 3 + 1];
      matched[m * 3 + 2] = sphere[s * 3 + 2];
    }
    at = end;
  }
  return matched;
}

export function buildData(modules: Modules): OrbitData {
  const { cols, rows } = darkCells(modules);
  return {
    count: cols.length,
    sphere: matchSphere(cols, rows),
    cols,
    rows,
    size: modules.length,
  };
}

export function makeConfig(
  canvas: number,
  size: number,
  count: number,
  reduced = false,
): OrbitConfig {
  const total = size + QUIET_ZONE * 2;
  const cell = canvas / total;
  const radius = canvas * 0.34;
  const tile =
    Math.sqrt((4 * Math.PI * radius * radius) / Math.max(1, count)) * 0.62;
  return {
    canvas,
    radius,
    cell,
    origin: cell * QUIET_ZONE,
    focal: canvas * 2.4,
    tile,
    spread: reduced ? 0 : WAVE_SPREAD,
  };
}

export function clamp01(v: number) {
  "worklet";
  return v < 0 ? 0 : v > 1 ? 1 : v;
}

export function ease(t: number) {
  "worklet";
  return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
}

export function wrapAngle(a: number) {
  "worklet";
  const t = a % (Math.PI * 2);
  return t > Math.PI ? t - Math.PI * 2 : t < -Math.PI ? t + Math.PI * 2 : t;
}

/** Local progress of one tile, delayed by how far down the sphere it starts. */
export function tileProgress(progress: number, y: number, spread: number) {
  "worklet";
  const delay = spread * (y + 1) * 0.5;
  return clamp01((progress - delay) / (1 - spread));
}

export const INK = [0.07, 0.14, 0.1];

/**
 * Writes five numbers per tile into `out`: centre x, centre y, side, landing
 * progress and depth. Fills `order` back to front. At progress 1
 * every tile sits exactly on its module cell.
 */
export function layoutTiles(
  progress: number,
  yaw: number,
  pitch: number,
  data: OrbitData,
  cfg: OrbitConfig,
  out: number[],
  order: number[],
) {
  "worklet";
  const half = cfg.canvas / 2;
  for (let i = 0; i < data.count; i += 1) {
    const sx0 = data.sphere[i * 3];
    const sy0 = data.sphere[i * 3 + 1];
    const sz0 = data.sphere[i * 3 + 2];
    const t = tileProgress(progress, sy0, cfg.spread);
    const e = ease(t);
    const turn = 1 - e;
    // Rotate by yaw then pitch, both unwinding to zero as the tile lands.
    const yawC = Math.cos(wrapAngle(yaw) * turn);
    const yawS = Math.sin(wrapAngle(yaw) * turn);
    const pitC = Math.cos(wrapAngle(pitch) * turn);
    const pitS = Math.sin(wrapAngle(pitch) * turn);
    const rx = sx0 * yawC + sz0 * yawS;
    const rz0 = -sx0 * yawS + sz0 * yawC;
    const ry = sy0 * pitC - rz0 * pitS;
    const rz = sy0 * pitS + rz0 * pitC;
    const qx = cfg.origin + (data.cols[i] + 0.5) * cfg.cell - half;
    const qy = cfg.origin + (data.rows[i] + 0.5) * cfg.cell - half;
    const lift = Math.sin(Math.PI * e) * cfg.radius * 0.28;
    const x = rx * cfg.radius * turn + qx * e;
    const y = ry * cfg.radius * turn + qy * e;
    const z = rz * cfg.radius * turn + lift;
    const persp = cfg.focal / (cfg.focal - z);
    const scale = persp * turn + e;
    out[i * 5] = half + x * scale;
    out[i * 5 + 1] = half + y * scale;
    // A little overlap at landing hides anti-aliasing seams between neighbours.
    out[i * 5 + 2] =
      (cfg.tile * turn + cfg.cell * e) * (persp * turn + e) + e * SEAM;
    out[i * 5 + 3] = e;
    out[i * 5 + 4] = z / cfg.radius;
    order[i] = i;
  }
  order.length = data.count;
  order.sort((a, b) => out[a * 5 + 4] - out[b * 5 + 4]);
}

/** Paper behind the code fades in late so contrast is full at the end. */
export function paperAlpha(progress: number) {
  "worklet";
  return clamp01((progress - 0.55) / 0.4);
}

/** Tiles stay the same ink on the sphere and in the code; depth reads through perspective. */
export function tileColor(e: number, depth: number, out: number[]) {
  "worklet";
  for (let k = 0; k < 3; k += 1) {
    out[k] = INK[k];
  }
}

import React, { useMemo, useState } from "react";
import { Pressable, Text, View } from "react-native";
import qrcode from "qrcode-generator";
import { OrbitQR } from "./OrbitQR";

// Any QR encoder works. This one is MIT licensed and has no native code.
function encode(text: string) {
  const q = qrcode(0, "M");
  q.addData(text);
  q.make();
  const n = q.getModuleCount();
  return Array.from({ length: n }, (_, r) =>
    Array.from({ length: n }, (_, c) => q.isDark(r, c)),
  );
}

export default function Example() {
  const [showCode, setShowCode] = useState(false);
  const [slow, setSlow] = useState(false);
  const modules = useMemo(() => encode("https://nativelet.netlify.app/"), []);
  return (
    <View style={{ alignItems: "center", gap: 18 }}>
      <View style={{ width: "100%", flexDirection: "row", justifyContent: "space-between", alignItems: "center", paddingHorizontal: 20 }}><Text style={{ fontSize: 10, letterSpacing: 1.5, color: "#315444" }}>ORBIT QR</Text><Pressable accessibilityRole="switch" accessibilityState={{ checked: slow }} accessibilityLabel="Slow motion" onPress={() => setSlow((v) => !v)} style={{ minHeight: 44, paddingHorizontal: 12, justifyContent: "center", borderRadius: 20, borderWidth: 1, borderColor: "#dce5d6", backgroundColor: "#f3f6ee" }}><Text style={{ fontSize: 10, color: "#315444" }}>Slow motion: {slow ? "on" : "off"}</Text></Pressable></View>
      <View style={{ borderRadius: 16, backgroundColor: "#eef3e8", overflow: "hidden" }}>
      <OrbitQR
        slowMotion={slow}
        modules={modules}
        size={300}
        showCode={showCode}
        label="QR code for nativelet.netlify.app"
      />
      </View>
      <Pressable
        accessibilityRole="button"
        accessibilityLabel={showCode ? "Back to sphere" : "Turn into QR code"}
        onPress={() => setShowCode((v) => !v)}
        style={{
          backgroundColor: "#14231b",
          paddingHorizontal: 22,
          paddingVertical: 12,
          borderRadius: 999,
        }}
      >
        <Text style={{ color: "#f4f7ef", fontWeight: "600" }}>
          {showCode ? "Back to sphere" : "Turn into QR"}
        </Text>
      </Pressable>
    </View>
  );
}
